def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the 1-filled rectangle that forms the canvas.
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in ones), max(r for r, c in ones)
    c0, c1 = min(c for r, c in ones), max(c for r, c in ones)
    panel = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    H, W = len(panel), len(panel[0])

    # The canvas is rotated clockwise.
    out = [[panel[H - 1 - r][c] for r in range(H)] for c in range(W)]

    # External singletons provide replacement colors for the isolated
    # single-cell marks in the canvas. Match by their order in reading order.
    external = []
    for r in range(h):
        for c in range(w):
            if not (r0 <= r <= r1 and c0 <= c <= c1) and grid[r][c] not in (0, 1):
                external.append(grid[r][c])

    marks = []
    for r in range(H):
        for c in range(W):
            v = panel[r][c]
            if v not in (0, 1):
                same_neighbors = any(
                    0 <= r + dr < H and 0 <= c + dc < W and panel[r + dr][c + dc] == v
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
                )
                if not same_neighbors:
                    marks.append((r, c))
    marks.sort()
    external.sort()
    for (r, c), color in zip(marks, external):
        out[c][H - 1 - r] = color
    return out
