    # The 1s form the canvas. The surrounding colored singletons are keys;
    # preserve the canvas and replace its singleton markers by the exterior
    # markers in reading order.
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    out = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    inside = []
    for r in range(len(out)):
        for c in range(len(out[0])):
            v = out[r][c]
            if v not in (0, 1) and not any(
                0 <= r + dr < len(out) and 0 <= c + dc < len(out[0])
                and out[r + dr][c + dc] == v
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))
            ):
                inside.append((r, c))

    outside = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 1)
               and not (r0 <= r <= r1 and c0 <= c <= c1)]
    inside.sort()
    outside.sort()
    for (r, c), (_, _, color) in zip(inside, outside):
        out[r][c] = color
    return out
